"use strict";
import { AnimatePresence, motion } from "framer-motion";
import { PositionStatus, ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { StakedStatusBadge } from "components/Liquidity/StakedStatusBadge";
import { getPositionUrl } from "components/Liquidity/utils";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import styled from "styled-components";
import { Flex, Text, useSporeColors } from "ui/src";
import { Chevron } from "ui/src/components/icons";
import { useDashContext } from "../DashContextProvider";
import StakedUnstakedAprEmissionsTradingFees from "./StakedUnstakedAprEmissionsTradingFees";
const ToggleButton = styled.button`
  all: unset;
  display: flex;
  gap: 4px;
  padding: 12px 18px;
  cursor: pointer;
  border-radius: 10px;
  align-items: center;
`;
function MeasuredExpand({ isExpanded, children }) {
  const measuredRef = useRef(null);
  const [contentHeight, setContentHeight] = useState(0);
  useLayoutEffect(() => {
    if (!isExpanded) return;
    const element = measuredRef.current;
    if (!element) return;
    console.log(element, "element");
    const updateSize = () => {
      setContentHeight(element.scrollHeight);
    };
    updateSize();
    const resizeObserver = new ResizeObserver(() => {
      updateSize();
    });
    resizeObserver.observe(element);
    return () => {
      resizeObserver.disconnect();
    };
  }, [isExpanded]);
  return <AnimatePresence initial={false}>
      {isExpanded ? <motion.div
    initial={{ height: 0, opacity: 0 }}
    animate={{ height: contentHeight, opacity: 1 }}
    exit={{ height: 0, opacity: 0 }}
    transition={{
      height: { duration: 0.25, ease: "easeInOut" },
      opacity: { duration: 0.15, ease: "easeOut" }
    }}
    style={{ overflow: "hidden" }}
  >
          <div ref={measuredRef} style={{ padding: "12px 18px" }}>
            {children}
          </div>
        </motion.div> : null}
    </AnimatePresence>;
}
export default function PositionRow({
  position,
  index,
  CurrencyDetails
}) {
  const { expandCollapse } = useDashContext();
  const [isExpanded, setIsExpanded] = useState(false);
  useEffect(() => {
    setIsExpanded(expandCollapse);
    return () => setIsExpanded(false);
  }, [expandCollapse]);
  const isV3 = position?.version === ProtocolVersion.V3;
  const positionId = isV3 ? position?.tokenId ? `#${position.tokenId}` : `#${index + 1}` : `#V2-${position.globalV2Index || index + 1}`;
  const isGaugePosition = position?.isGaugePosition;
  const isStaked = position?.isStaked;
  const hasGaugeStake = position?.hasGaugeStake;
  const isPartiallyStaked = position?.isPartiallyStaked;
  const stakingPercentage = position?.stakingPercentage || 0;
  const positionUrl = getPositionUrl(position);
  const colors = useSporeColors();
  const getStatusColor = () => {
    switch (position?.status) {
      case PositionStatus.IN_RANGE:
        return colors.statusSuccess.val;
      case PositionStatus.OUT_OF_RANGE:
        return colors.statusCritical.val;
      case PositionStatus.CLOSED:
        return colors.neutral3.val;
      default:
        return colors.neutral3.val;
    }
  };
  return <Flex
    flexDirection="column"
    ml={"$spacing12"}
    $md={{ ml: 0 }}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    transition="all 0.2s ease"
    hoverStyle={{ backgroundColor: "$surface1Hovered" }}
  >
      <ToggleButton
    onClick={() => setIsExpanded(!isExpanded)}
    type="button"
    role="button"
    aria-label="toggle-position-details"
  >
        <Flex row gap={"$gap12"} justifyContent="space-between" alignItems="center" flexWrap="wrap" width={"100%"}>
          <Flex row gap={"$gap16"} alignItems="center">
            <Chevron
    transition="transform 0.2s ease"
    transform={isExpanded ? "rotate(270deg)" : "rotate(180deg)"}
    size={20}
    color={"$neutral1"}
  />
            <Text variant="buttonLabel4">Position {positionId}</Text>
            {isPartiallyStaked ? <Flex backgroundColor={"$accent1"} px={"$spacing4"} py={"$spacing2"} borderRadius={"$rounded4"}>
                <Text variant="body4" fontSize={10} color={"$surface1"} fontWeight="600">
                  {stakingPercentage}% STAKED
                </Text>
              </Flex> : isStaked ? <StakedStatusBadge position={position} hasGauge={hasGaugeStake} size="small" /> : hasGaugeStake ? <StakedStatusBadge position={position} hasGauge={hasGaugeStake} size="small" /> : null}
          </Flex>

          <Flex row gap={"$gap12"} alignItems="center" alignSelf="flex-end">
            <Flex $lg={{ display: "none" }}>
              <CurrencyDetails position={position} isV3={isV3} getStatusColor={getStatusColor} />
            </Flex>
            <Link to={positionUrl} className="text-decoration-none" onClick={(e) => e.stopPropagation()}>
              <Flex
    py={"$spacing8"}
    px={"$spacing12"}
    borderRadius={"$rounded12"}
    transition="all 0.2s ease"
    borderWidth={1}
    borderColor={"$surface3"}
    backgroundColor={isStaked ? "$surface2" : "$surface1"}
    hoverStyle={{ backgroundColor: "$surface1Hovered" }}
  >
                <Text variant="buttonLabel4">Manage</Text>
              </Flex>
            </Link>
          </Flex>
        </Flex>
      </ToggleButton>

      {
    /* Expandable content */
  }
      <MeasuredExpand isExpanded={isExpanded}>
        <Flex display="none" $lg={{ display: "block" }} mb={"$spacing24"}>
          <CurrencyDetails position={position} isV3={isV3} getStatusColor={getStatusColor} />
        </Flex>
        <StakedUnstakedAprEmissionsTradingFees position={position} isLoading={false} />
      </MeasuredExpand>
    </Flex>;
}
